// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IPonsV2FeeEscrow} from "./interfaces/ILaunchpadV2.sol";

/**
 * @title PonsV2FeeEscrow
 * @notice Holds every v2 recipient's claimable balance in one place, so
 * protocol and creators claim revenue from across all of their pools in a
 * single transaction instead of collecting per position. Revenue arrives in
 * whichever asset the launch trades against: native ETH for a native launch,
 * and the launch's ERC-20 quote asset otherwise. Both the bonding curve and
 * the post-graduation PonsV2MemeHook credit the same way, so a recipient's
 * balance is denominated identically before and after graduation.
 */
contract PonsV2FeeEscrow is ReentrancyGuard, IPonsV2FeeEscrow {
    using SafeERC20 for IERC20;

    error ZeroAddress();
    error NoBalance();
    error TransferFailed();
    error InsufficientBalance(uint256 requested, uint256 available);

    event Credited(address indexed recipient, address indexed depositor, uint256 amount);
    event CreditedToken(address indexed recipient, address indexed token, address indexed depositor, uint256 amount);
    event Claimed(address indexed recipient, uint256 amount);
    event ClaimedToken(address indexed recipient, address indexed token, uint256 amount);

    mapping(address recipient => uint256 amount) private _balances;
    mapping(address recipient => mapping(address token => uint256 amount)) private _tokenBalances;

    /**
     * @notice Credits `msg.value` to `recipient`'s claimable native ETH balance.
     * @dev Permissionless by design: the caller can only ever add value they
     * already attached to the call, so there is no privilege to gate.
     */
    function credit(address recipient) external payable {
        if (recipient == address(0)) revert ZeroAddress();
        if (msg.value == 0) return;
        _balances[recipient] += msg.value;
        emit Credited(recipient, msg.sender, msg.value);
    }

    /**
     * @notice Pulls `amount` of `token` from the caller and credits it to `recipient`.
     * @dev Permissionless by design: the caller can only credit tokens they
     * already hold and approve, so there is no privilege to gate. Credits
     * the actual balance delta rather than the nominal `amount`, so a
     * fee-on-transfer or deflationary pairToken can never make this
     * contract record more credited liability than it actually holds,
     * which would otherwise starve whichever recipient claims that token
     * last.
     */
    function creditToken(address recipient, address token, uint256 amount) external nonReentrant {
        if (recipient == address(0) || token == address(0)) revert ZeroAddress();
        if (amount == 0) return;
        uint256 balanceBefore = IERC20(token).balanceOf(address(this));
        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
        uint256 received = IERC20(token).balanceOf(address(this)) - balanceBefore;
        if (received == 0) return;
        _tokenBalances[recipient][token] += received;
        emit CreditedToken(recipient, token, msg.sender, received);
    }

    /**
     * @notice Pays out the caller's entire claimable native ETH balance.
     */
    function claim() external nonReentrant returns (uint256 amount) {
        amount = _claim(_balances[msg.sender]);
    }

    /**
     * @notice Pays out `amount` of the caller's claimable native ETH balance.
     */
    function claim(uint256 amount) external nonReentrant returns (uint256) {
        return _claim(amount);
    }

    /**
     * @notice Pays out the caller's entire claimable balance of `token`.
     */
    function claimToken(address token) external nonReentrant returns (uint256 amount) {
        amount = _claimToken(token, _tokenBalances[msg.sender][token]);
    }

    /**
     * @notice Pays out `amount` of the caller's claimable balance of `token`.
     * @dev A recipient's balance aggregates credits from every launch, curve,
     * hook and buyback release, and `creditToken` is permissionless, so a
     * third party can enlarge that figure at will. Against a token with a
     * fixed maximum per transfer, a single full-balance claim would then
     * revert and leave the recipient unable to draw any of it. Choosing the
     * amount keeps the aggregate from being a single point of failure, and
     * lets a recipient work around any per-transfer limit its quote asset
     * imposes.
     */
    function claimToken(address token, uint256 amount) external nonReentrant returns (uint256) {
        return _claimToken(token, amount);
    }

    /**
     * @dev Shared debit path for both native claim entry points.
     */
    function _claim(uint256 amount) private returns (uint256) {
        if (amount == 0) revert NoBalance();
        uint256 balance = _balances[msg.sender];
        if (amount > balance) revert InsufficientBalance(amount, balance);

        _balances[msg.sender] = balance - amount;
        (bool sent,) = payable(msg.sender).call{value: amount}("");
        if (!sent) revert TransferFailed();

        emit Claimed(msg.sender, amount);
        return amount;
    }

    /**
     * @dev Shared debit path for both ERC-20 claim entry points.
     */
    function _claimToken(address token, uint256 amount) private returns (uint256) {
        if (amount == 0) revert NoBalance();
        uint256 balance = _tokenBalances[msg.sender][token];
        if (amount > balance) revert InsufficientBalance(amount, balance);

        _tokenBalances[msg.sender][token] = balance - amount;
        IERC20(token).safeTransfer(msg.sender, amount);

        emit ClaimedToken(msg.sender, token, amount);
        return amount;
    }

    /**
     * @notice Returns the claimable native ETH balance for `recipient`.
     */
    function balanceOf(address recipient) external view returns (uint256) {
        return _balances[recipient];
    }

    /**
     * @notice Returns the claimable balance of `token` for `recipient`.
     */
    function balanceOfToken(address recipient, address token) external view returns (uint256) {
        return _tokenBalances[recipient][token];
    }
}

contracts/src/v2/interfaces/ILaunchpadV2.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

/**
 * @notice Shared pons v2 interfaces: fee escrow, fee policy, and the launch
 * factory/curve records. Uniswap V4 core and periphery types are imported
 * directly from the vendored packages by the contracts that need them,
 * rather than re-declared here.
 */

/**
 * @notice Claimable balance ledger shared by every v2 bonding curve and the
 * meme hook. Native ETH crediting is permissionless (callers attach the ETH
 * they are crediting). Token crediting requires the caller to hold the
 * tokens themselves, pulled via `transferFrom`, so it is equally safe to
 * leave open. Token support exists for launches whose deployer-chosen
 * pairToken is a non-native ERC-20: those curves trade and credit in that
 * asset from the first trade through to graduation.
 */
interface IPonsV2FeeEscrow {
    function credit(address recipient) external payable;
    function creditToken(address recipient, address token, uint256 amount) external;
    function claim() external returns (uint256 amount);
    function claim(uint256 amount) external returns (uint256);
    function claimToken(address token) external returns (uint256 amount);
    function claimToken(address token, uint256 amount) external returns (uint256);
    function balanceOf(address recipient) external view returns (uint256);
    function balanceOfToken(address recipient, address token) external view returns (uint256);
}

/**
 * @notice Fee terms frozen for one launch when its curve is created and its
 * graduated pool is registered. Global hook configuration only governs
 * launches created after a later policy update.
 */
struct FeePolicySnapshot {
    address protocolFeeRecipient;
    uint16 protocolFeeShareBps;
    uint16 buybackBurnBps;
    uint16 hookFeeBps;
    uint16 maxInternalPriceImpactBps;
}

/**
 * @notice Protocol-owned fee policy read by every bonding curve and by the
 * meme hook. The current policy is snapshotted at launch, while the live
 * sweep operator remains rotatable for operational liveness.
 */
interface IPonsV2FeePolicy {
    function protocolFeeShareBps() external view returns (uint256);
    function buybackBurnBps() external view returns (uint256);
    function protocolFeeRecipient() external view returns (address);
    function feeEscrow() external view returns (IPonsV2FeeEscrow);
    // Ceiling on how much a single internal buyback conversion is allowed
    // to move the pool's own price, read by the meme hook's real internal
    // swaps and by the bonding curve's pre-graduation buyback pricing so
    // both phases apply the same conservative bound.
    function maxInternalPriceImpactBps() external view returns (uint256);
    function feeSweepOperator() external view returns (address);
    function currentFeePolicy() external view returns (FeePolicySnapshot memory);
}

/**
 * @notice Minimal ERC-721 receiver signature used by PonsV2LaunchLocker to
 * accept the graduated Uniswap V4 position NFT.
 */
interface IERC721ReceiverLike {
    function onERC721Received(address operator, address from, uint256 tokenId, bytes calldata data)
        external
        returns (bytes4);
}

/**
 * @notice Graduation proceeds in two phases so the slippage-sensitive step
 * is never bundled with the automatic, threshold-crossing trigger:
 * - NotGraduated: still trading on the bonding curve.
 * - Swept: the curve has been drained (fees swept, trading halted, ETH and
 *   the remaining token supply pulled into the factory); still needs a V4
 *   pool.
 * - PoolCreated: the V4 pool exists, its full-range position is locked, and
 *   the meme hook is registered for it.
 * - Rescued: the swept reserves were released manually because the launch's
 *   quote asset stopped being able to deliver an exact transfer, which no
 *   retry of the seed step could ever satisfy. Terminal, like PoolCreated.
 */
enum GraduationPhase {
    NotGraduated,
    Swept,
    PoolCreated,
    Rescued
}

/**
 * @notice Record kept by PonsV2LaunchFactory for every launch, readable by
 * the locker and by off-chain indexers.
 */
interface IPonsV2LaunchFactory {
    struct LaunchedToken {
        address token;
        address curve;
        address deployer;
        address creatorFeeRecipient;
        address pairToken;
        uint256 graduationThreshold;
        // Snapshotted from the launch config at launch time, so a later
        // config edit can never change the pool a token graduates into.
        uint24 poolFee;
        int24 tickSpacing;
        // Creator-chosen at launch, capped by the protocol's maxCreatorTaxBps
        // at the time of launch; an additional trade fee charged the same
        // way the base fee is, paid entirely to the creator.
        uint16 creatorTaxBps;
        bool buybackEnabled;
        GraduationPhase phase;
        uint256 sweptQuote;
        uint256 sweptTokens;
        uint256 sweptAt;
        bool exists;
    }

    function getLaunchedToken(address token) external view returns (LaunchedToken memory);
}

/**
 * @notice Narrow surface the factory needs from a bonding curve to trigger
 * graduation once the ETH threshold has been crossed.
 */
interface IPonsV2BondingCurve {
    function token() external view returns (address);
    function pairToken() external view returns (address);
    function graduationThreshold() external view returns (uint256);
    function graduated() external view returns (bool);
    function quoteReserve() external view returns (uint256);
    function realQuoteReserve() external view returns (uint256);
    function tokenReserve() external view returns (uint256);
    function readyToGraduate() external view returns (bool);
    function sweepFees(uint256 minBuybackTokensOut) external;
    function graduate(address recipient) external returns (uint256 ethOut, uint256 tokenOut);
}
